212: /** Recompute a decision every time. No imported context field grants execution authority. */
213: export function nextAction(task, host) {
214:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
215:   const workflow = definition(task, host.registry, host.inventory);
216:   assert(Object.keys(task.steps).length === workflow.stages.length && workflow.stages.every(s => task.steps[s.id]), 'Task stages differ from Registry');
217:   if (!host.scopeReviewed) return { action: 'evidence_insufficient', reason: 'risk_and_dependency_scope_not_reviewed' };
218:   if (workflow.stages.length > 1 && !host.continuationAuthorized) return { action: 'permission_blocked', reason: 'continuous_workflow_not_authorized' };
219:   if (host.openDecisions?.length) return { action: 'decision_required', skill: 'requirements-clarification', reason: host.openDecisions.join(', ') };
220:   if (host.activeStops?.length) return { action: 'blocked', reason: host.activeStops.join(', ') };

221:   const recovery = recoveryBinding(task, host);
222:   const recoveryCheck = recovery && host.recoveryChecks?.get(recovery);
223:   if (recovery && (!recoveryCheck?.source || recoveryCheck.reconciled !== true)) return { action: 'blocked', reason: 'recovered_execution_state_needs_reconciliation' };
224:   // Unknown effects cannot disappear when an optional predicate or prerequisite changes.
225:   const inflight = workflow.stages.find(stage => ['running', 'interrupted'].includes(task.steps[stage.id].status));
226:   if (inflight) return { stage: inflight.id, skill: inflight.skill, action: 'blocked', reason: 'inflight_operation_needs_reconciliation' };
227:   const uncertain = workflow.stages.find(stage => task.steps[stage.id].effect_state === 'uncertain');
228:   if (uncertain) return { stage: uncertain.id, skill: uncertain.skill, action: 'validation_failed', reason: 'failed_operation_needs_reconciliation' };
229:   const completed = new Set();
230:   for (const stage of workflow.stages) {
231:     const step = task.steps[stage.id];
232:     if (stage.prerequisites.some(id => !completed.has(id))) continue;
233:     if (step.request_binding && step.request_binding !== digest(host.requests?.[stage.id])) {
234:       return { stage: stage.id, skill: stage.skill, action: 'evidence_insufficient', reason: 'operation_scope_changed' };
235:     }
236:     const applies = condition(task, stage.condition, host);
237:     const decision = { stage: stage.id, skill: stage.skill };
238:     const stopAssessments = [...new Set([...(workflow.stop_conditions ?? []), ...stage.stop_conditions])].map(name => [name, condition(task, name, host)]);
239:     const stop = stopAssessments.find(([, value]) => value === true);
240:     if (stop) return { ...decision, action: 'blocked', reason: `stop_condition:${stop[0]}` };
241:     const unknownStop = stopAssessments.find(([, value]) => value === undefined);
242:     if (unknownStop) return { ...decision, action: 'evidence_insufficient', reason: `stop_condition_unknown:${unknownStop[0]}` };
243:     if (applies === undefined) return { ...decision, action: 'evidence_insufficient', reason: `condition_unknown:${stage.condition}` };
244:     // Completed effects stay protected even when applicability changes. A new receipt
245:     // is not a reconciliation of the previous attempt's potentially different effects.
246:     const wasCompleted = ['completed', 'reused'].includes(step.status);
247:     const effectful = step.effect_state === 'known' || writes(stage, host)
248:       || host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files');
249:     if (stage.type === 'skill' && wasCompleted) {
250:       const denied = permission(stage.skill, stage, task, host);
251:       if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
252:       if (!stepEvidence(task, stage, host) && effectful) return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
253:     }
254:     if (!applies) {
255:       if (!stage.optional) return { ...decision, action: 'evidence_insufficient', reason: `required_condition_false:${stage.condition}` };
256:       // Applicability must not erase a completed operation or its known effects.
257:       if (['completed', 'reused'].includes(step.status)) { completed.add(stage.id); continue; }
258:       if (step.status !== 'skipped' || step.condition_binding !== digest(host.conditions[stage.condition])) return { ...decision, action: 'skip', reason: `not_applicable:${stage.condition}` };
259:       completed.add(stage.id); continue;
260:     }
261:     if (stage.type === 'gate') {
262:       const children = workflow.stages.filter(s => s.approval_gate === stage.id);
263:       if (!children.length) return { ...decision, action: 'permission_blocked', reason: 'gate_has_no_consumer' };
264:       for (const child of children) {
265:         const denied = permission(child.skill, child, task, host);
266:         if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
267:       }
268:       // Always re-evaluate gates against host grants, never reuse persisted approval.
269:       if (step.status !== 'completed') return { ...decision, action: 'approve', reason: 'existing_scoped_host_authorization' };
270:       completed.add(stage.id); continue;
271:     }
272:     const denied = permission(stage.skill, stage, task, host);
273:     if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
274:     if (['completed', 'reused'].includes(step.status) && stepEvidence(task, stage, host)) {
275:       completed.add(stage.id); continue;
276:     }
277:     const failure = step.status === 'validation_failed';
278:     if (failure) return { ...decision, action: 'validation_failed', reason: step.reason || 'explicit_retry_required' };
279:     // Risk checks are additive obligations referencing existing Skills, not new workflows.
280:     if (potentiallyEffectful(stage, host)) {
281:       const gap = (host.risks ?? []).flatMap(r => host.registry.coordination?.risk_requirements?.[r]?.before_write ?? [{ claim: `unclassified-risk:${r}` }])
282:         .find(r => !requirement(task, r, host));
283:       if (gap) return { ...decision, action: 'risk_check', requirement: gap, reason: 'risk_requires_additional_evidence' };
284:     }
285:     const candidate = host.reuse?.[stage.id];
286:     if (candidate) {
287:       const provisional = copy(task); provisional.steps[stage.id].evidence_ids = candidate;
288:       if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: candidate, reason: 'valid_existing_result' };
289:     }
290:     if ((writes(stage, host) || step.effect_state === 'known' || host.requests[stage.id].capabilities.some(c => c !== 'read_files')) && ['completed', 'reused'].includes(step.status)) {
291:       return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
292:     }
293:     const unresolved = unresolvedFailures(task, host).find(failed => {
294:       const repair = host.failureRepairs?.get(digest(failed));
295:       return !repair?.source || repair.stages?.[stage.id] !== digest(host.requests[stage.id]);
296:     });
297:     if (unresolved) return { ...decision, action: evidenceValidity(unresolved, host).status === 'unknown' ? 'evidence_insufficient' : 'validation_failed', reason: 'unresolved_current_test_failure', evidence_id: unresolved.id };
298:     return { ...decision, action: 'execute', reason: ['completed', 'reused'].includes(step.status) ? 'prior_evidence_stale_or_unknown' : 'applicable_stage', mode: host.execution === 'same_agent' ? 'same_agent' : 'manual_handoff' };
299:   }
300:   if (completed.size !== workflow.stages.length) return { action: 'evidence_insufficient', reason: 'unresolved_dependencies' };
301:   const obligations = [
302:     ...task.acceptance.map(id => ({ claim: `acceptance:${id}` })),
303:     ...([...completed].some(id => {
304:       const stage = workflow.stages.find(s => s.id === id);
305:       return task.steps[id].status !== 'skipped'
306:         && ['feature-implementation', 'safe-fix-implementation', 'safe-test-implementation'].includes(stage.skill);
307:     }) ? [{ claim: 'behavior-validation', kind: 'test' }] : []),
308:     ...(host.deliveryRequirements ?? []),
309:     ...(host.risks ?? []).flatMap(r => {
310:       const rules = host.registry.coordination?.risk_requirements?.[r];
311:       return rules ? [...rules.before_write, ...rules.before_delivery] : [{ claim: `unclassified-risk:${r}` }];
312:     }),
313:   ];
314:   const failure = unresolvedFailures(task, host)[0];
315:   if (failure) return { action: evidenceValidity(failure, host).status === 'unknown' ? 'evidence_insufficient' : 'validation_failed', reason: 'unresolved_current_test_failure', evidence_id: failure.id };
316:   const missing = obligations.filter(r => !requirement(task, r, host));
317:   if (task.unresolved.length || missing.length) return { action: 'evidence_insufficient', reason: 'delivery_not_proven', missing };
318:   return { action: 'complete', reason: 'applicable_stages_and_acceptance_proven', release_authorized: false };
319: }
