321: function event(task, stage, status, reason) {
322:   task.current_stage = stage;
323:   task.history.push({ sequence: task.history.length + 1, stage, status, reason });
324: }
325: 
326: export function advance(task, host) {
327:   const action = nextAction(task, host);
328:   if (['skip', 'approve', 'reuse', 'execute'].includes(action.action)) {
329:     const step = task.steps[action.stage];
330:     step.status = { skip: 'skipped', approve: 'completed', reuse: 'reused', execute: 'running' }[action.action];
331:     step.reason = action.reason;
332:     if (['execute', 'reuse'].includes(action.action)) step.request_binding = digest(host.requests[action.stage]);
333:     if (action.action === 'execute') {
334:       step.attempts++;
335:       step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'uncertain' : 'none';
336:     }
337:     if (action.action === 'skip') {
338:       const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === action.stage);
339:       step.condition_binding = digest(host.conditions[stage.condition]);
340:     }
341:     if (action.action === 'reuse') step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'known' : 'none';
342:     if (action.evidence_ids) step.evidence_ids = action.evidence_ids;
343:     event(task, action.stage, step.status, action.reason);
344:   }
345:   task.next_actions = [action];
346:   return action;
347: }
348: 
349: export function finishStep(task, stageId, evidenceIds, host, failureReason = null) {
350:   const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === stageId);
351:   const step = task.steps[stageId];
352:   assert(stage && step?.status === 'running', 'Only a running stage may finish');
353:   assert(step.request_binding === digest(host.requests[stageId]), 'Operation scope changed while running');
354:   const denied = permission(stage.skill, stage, task, host);
355:   assert(!denied, denied);
356:   if (failureReason) { step.status = 'validation_failed'; step.reason = failureReason; step.evidence_ids = [...evidenceIds]; }
357:   else {
358:     const provisional = copy(task); provisional.steps[stageId].evidence_ids = evidenceIds;
359:     assert(stepEvidence(provisional, stage, host), 'Completion requires valid, scoped evidence and independent review');
360:     step.evidence_ids = [...evidenceIds]; step.status = 'completed'; step.effect_state = step.effect_state === 'none' ? 'none' : 'known';
361:   }
362:   event(task, stageId, step.status, failureReason || 'observed_completion');
363: }
