365: /** Reopening is an explicit host decision; only descendants are reopened.
366:  * Evidence is retained, so still-valid independent checks can be reused.
367:  */
368: export function reopen(task, stageId, host, { reason, source, safeToRetry = false } = {}) {
369:   assert(reason && source, 'Reopen requires a sourced reason');
370:   const workflow = definition(task, host.registry, host.inventory);
371:   assert(task.steps[stageId], 'Unknown stage');
372:   const affected = new Set([stageId]);
373:   let changed = true;
374:   while (changed) { changed = false; for (const stage of workflow.stages) {
375:     if (!affected.has(stage.id) && stage.prerequisites.some(id => affected.has(id))) { affected.add(stage.id); changed = true; }
376:   } }
377:   for (const id of affected) {
378:     const stage = workflow.stages.find(s => s.id === id);
379:     if (['running', 'interrupted'].includes(task.steps[id].status)
380:         || task.steps[id].effect_state === 'uncertain'
381:         || ((writes(stage, host) || task.steps[id].effect_state === 'known' || host.requests?.[id]?.capabilities?.some(c => c !== 'read_files')) && ['completed', 'reused', 'validation_failed'].includes(task.steps[id].status))) {
382:       assert(safeToRetry && host.reconciled?.has(reconciliationBinding(task, id, host)), 'Unknown side effects must be reconciled before retry');
383:     }
384:   }
385:   for (const id of affected) {
386:     const previous = task.steps[id].request_binding;
387:     task.steps[id].status = 'pending'; task.steps[id].effect_state = 'reconciled';
388:     delete task.steps[id].request_binding;
389:     event(task, id, 'pending', `${reason} (${source})`);
390:     if (previous) task.history.at(-1).previous_request_binding = previous;
391:   }
392: }
